import unittest
from slug import slug
class Contract(unittest.TestCase):
    def test_spaces(self): self.assertEqual(slug("  Hello   World  "), "hello-world")
    def test_tabs(self): self.assertEqual(slug("One\tTwo\nThree"), "one-two-three")
    def test_unicode(self): self.assertEqual(slug("Straße"), "strasse")
    def test_empty(self): self.assertEqual(slug(" \t"), "")
    def test_punctuation(self): self.assertEqual(slug("A.B"), "a.b")
